            modelBuilder.Entity("HassanAdly.Domain.Entities.AdminRefreshToken", b =>
                {
                    b.HasOne("HassanAdly.Domain.Entities.AdminUser", "AdminUser")
                        .WithMany("RefreshTokens")
                        .HasForeignKey("AdminUserId")
                        .OnDelete(DeleteBehavior.Cascade)
                        .IsRequired();

                    b.Navigation("AdminUser");
                });

            modelBuilder.Entity("HassanAdly.Domain.Entities.AudioTrack", b =>
                {
                    b.HasOne("HassanAdly.Domain.Entities.Qiraa", "Qiraa")
                        .WithMany("AudioTracks")
                        .HasForeignKey("QiraaId")
                        .OnDelete(DeleteBehavior.Cascade)
                        .IsRequired();

                    b.HasOne("HassanAdly.Domain.Entities.Sheikh", "Sheikh")
                        .WithMany("AudioTracks")
                        .HasForeignKey("SheikhId")
